// ─── DID YOU KNOW? — 500+ WORLD CUP FACTS ────────────────────────────────────
// Categories: HISTORY · RECORDS · GOALS · PLAYERS · HOSTS · UPSETS · ODDITIES · WC2026

var FACTS = [

// ── HISTORY ───────────────────────────────────────────────────────────────────
{c:'HISTORY', t:'The first World Cup', f:'The first FIFA World Cup was held in Uruguay in 1930. Only 13 teams participated — just 4 from Europe, who had to travel by ship for over two weeks to get there.'},
{c:'HISTORY', t:'Uruguay vs Argentina', f:'The first World Cup final was played on 30 July 1930. Uruguay beat Argentina 4–2 in front of 68,000 fans in Montevideo.'},
{c:'HISTORY', t:'No European hosts', f:'The first three World Cups (1930, 1934, 1938) alternated between South America and Europe — causing such bitter disputes that Uruguay refused to defend their title in Italy in 1934.'},
{c:'HISTORY', t:'War breaks the run', f:'The World Cup was cancelled in 1942 and 1946 due to World War II — the only two editions ever missed.'},
{c:'HISTORY', t:'Brazil 1950 — no final', f:'The 1950 World Cup had no knockout final. Brazil needed only a draw in the last group game against Uruguay — but lost 2–1 in what became known as the "Maracanazo".'},
{c:'HISTORY', t:'The Jules Rimet Trophy', f:'The original World Cup trophy was named the Jules Rimet Trophy after the FIFA president who created the tournament. Brazil won it permanently in 1970 after their third title.'},
{c:'HISTORY', t:'Stolen twice', f:'The Jules Rimet Trophy was stolen twice — once in England in 1966 (found by a dog named Pickles) and again in Brazil in 1983, where it was never recovered.'},
{c:'HISTORY', t:'England\'s finest hour', f:'England\'s only World Cup triumph came on home soil in 1966. They beat West Germany 4–2 in extra time at Wembley — Geoff Hurst scoring the only hat-trick in a World Cup final.'},
{c:'HISTORY', t:'The Hand of God', f:'In the 1986 quarter-final, Diego Maradona punched the ball into the net with his hand against England. When asked about it, he said it was "a little with the head of Maradona and a little with the hand of God".'},
{c:'HISTORY', t:'That other 1986 goal', f:'Four minutes after the Hand of God, Maradona scored what FIFA voted the Goal of the Century — dribbling past five England players from his own half. One of sport\'s greatest moments.'},
{c:'HISTORY', t:'1994 — no goals in the final', f:'The 1994 World Cup final between Brazil and Italy was the first to end 0–0 after extra time. Brazil won on penalties — the first final decided by a shootout.'},
{c:'HISTORY', t:'France 1998 shock', f:'At France 1998, reigning champions Brazil were thrashed 3–0 by the hosts in the final. Ronaldo had a mysterious fit the night before the match, starting a controversy that was never fully explained.'},
{c:'HISTORY', t:'The Miracle of Bern', f:'West Germany\'s 3–2 win over Hungary in the 1954 final is called the "Miracle of Bern". Hungary were unbeaten in 4 years and had thrashed Germany 8–3 in the group stage weeks earlier.'},
{c:'HISTORY', t:'Italy\'s back-to-back', f:'Italy won consecutive World Cups in 1934 and 1938 — the only nation to do so. Vittorio Pozzo is the only manager to win the World Cup twice.'},
{c:'HISTORY', t:'Brazil\'s five titles', f:'Brazil remain the only nation to have won five World Cups: 1958, 1962, 1970, 1994 and 2002. They\'re also the only team to have qualified for every single tournament.'},
{c:'HISTORY', t:'Pelé\'s teen triumph', f:'Pelé was just 17 years and 249 days old when Brazil won the 1958 World Cup. He scored twice in the final — becoming the youngest ever World Cup winner.'},
{c:'HISTORY', t:'Germany\'s consistency', f:'Germany (West and unified) have reached the World Cup final more times than any other nation — 8 times in total. They\'ve won 4 and lost 4.'},
{c:'HISTORY', t:'1966 and all that', f:'The 1966 World Cup saw the most goals disallowed in final history. Geoff Hurst\'s controversial third goal — did it cross the line? — is still debated 60 years later.'},
{c:'HISTORY', t:'African pioneers', f:'Morocco became the first African nation to reach a World Cup semi-final at Qatar 2022. Their run included beating Spain and Portugal.'},
{c:'HISTORY', t:'Maracana capacity', f:'The 1950 World Cup "final" between Brazil and Uruguay was watched by an estimated 199,854 people at the Maracanã — the largest crowd ever at a football match.'},
{c:'HISTORY', t:'Host nation wins', f:'Of the 22 World Cups held before 2026, the host nation won 6 times: Uruguay (1930), Italy (1934), England (1966), West Germany (1974), Argentina (1978) and France (1998).'},
{c:'HISTORY', t:'South Africa 2010', f:'South Africa 2010 was the first World Cup held on the African continent. The vuvuzela became the unexpected soundtrack of the tournament.'},
{c:'HISTORY', t:'Japan and Korea 2002', f:'The 2002 World Cup was the first co-hosted edition and the first in Asia. South Korea reached the semi-finals — the best-ever run by an Asian team before Morocco\'s 2022 run.'},
{c:'HISTORY', t:'Russia 2018', f:'Russia 2018 was the first World Cup held in Eastern Europe. Croatia, a nation of just 4 million people, reached the final — their best ever performance.'},
{c:'HISTORY', t:'Qatar 2022', f:'Qatar 2022 was the first World Cup held in the Middle East and the first played in November-December due to the extreme summer heat.'},
{c:'HISTORY', t:'2026: the biggest ever', f:'The 2026 World Cup is the first with 48 teams — up from 32. It\'s jointly hosted by the USA, Canada and Mexico, making it the first three-nation host in history.'},
{c:'HISTORY', t:'USA 1994 attendance', f:'USA 1994 still holds the record for total tournament attendance — 3.5 million fans across 52 games. Americans who claimed to not care about football turned up in vast numbers.'},

// ── RECORDS ───────────────────────────────────────────────────────────────────
{c:'RECORDS', t:'Top scorer of all time', f:'Miroslav Klose of Germany holds the all-time record with 16 World Cup goals across four tournaments (2002, 2006, 2010, 2014). He surpassed Ronaldo\'s record of 15 in the 2014 semi-final.'},
{c:'RECORDS', t:'Most caps at a World Cup', f:'Lothar Matthäus of Germany appeared in 25 World Cup matches across five tournaments — the most appearances by any player in history.'},
{c:'RECORDS', t:'Most finals', f:'Germany and Brazil have both appeared in 8 World Cup finals. Germany have won 4, lost 4. Brazil have won 5, lost 3.'},
{c:'RECORDS', t:'Youngest scorer', f:'Pelé is the youngest player to score at a World Cup — aged 17 years and 239 days when he scored against Wales in the 1958 quarter-final.'},
{c:'RECORDS', t:'Oldest scorer', f:'Roger Milla scored for Cameroon against Russia at the 1994 World Cup at the age of 42 years and 39 days — the oldest scorer in World Cup history.'},
{c:'RECORDS', t:'Fastest goal', f:'Hakan Şükür of Turkey scored after just 11 seconds against South Korea in the 2002 third-place play-off — the fastest goal in World Cup history.'},
{c:'RECORDS', t:'Biggest win', f:'Hungary beat El Salvador 10–1 in the 1982 group stage — the largest margin of victory in World Cup history. László Kiss scored three goals in 7 minutes coming off the bench.'},
{c:'RECORDS', t:'Most goals in a match', f:'Austria beat Switzerland 7–5 in a 1954 quarter-final — 12 goals in total, the highest-scoring match ever at a World Cup.'},
{c:'RECORDS', t:'Most red cards in a match', f:'The 2006 quarter-final between Portugal and Netherlands had 4 red cards and 16 yellow cards — nicknamed "The Battle of Nuremberg". Russia referee Valentin Ivanov was widely criticised.'},
{c:'RECORDS', t:'Most WC appearances', f:'Five players have appeared in five separate World Cup tournaments. Antonio Carbajal (Mexico, 1950–1966) was the first. Lothar Matthäus, Rafael Márquez, Andrés Guardado, and Gianluigi Buffon later matched the feat.'},
{c:'RECORDS', t:'Longest unbeaten run', f:'Italy went 35 games unbeaten at World Cups from 1930 to 1950 — including the two title wins in 1934 and 1938.'},
{c:'RECORDS', t:'Most consecutive wins', f:'Brazil won 11 consecutive World Cup matches between 2002 and 2006 — the longest winning streak in tournament history.'},
{c:'RECORDS', t:'Most goals in a tournament', f:'Just Fontaine of France scored 13 goals at the 1958 World Cup — in just 6 games. This single-tournament record has never been beaten or even seriously threatened.'},
{c:'RECORDS', t:'Golden Boot winners', f:'Three players have won the Golden Boot twice: Gary Lineker, Ronaldo and Gerd Müller. None of them ever won the tournament with their country.'},
{c:'RECORDS', t:'Most clean sheets', f:'Peter Shilton kept 10 clean sheets across two World Cups for England (1982 and 1986) — the most in tournament history.'},
{c:'RECORDS', t:'Longest penalty shootout', f:'The longest penalty shootout in World Cup history was at USA 1994: Sweden beat Romania 5–4 after 10 kicks each in the quarter-finals.'},
{c:'RECORDS', t:'Most saves', f:'Manuel Neuer made 27 saves in the 2014 World Cup — but Germany won it. His sweeper-keeper performances became the stuff of legend.'},
{c:'RECORDS', t:'First hat-trick', f:'Bert Patenaude of the USA scored the first hat-trick in World Cup history against Paraguay at the 1930 tournament — though it was not officially recognised until 2006.'},
{c:'RECORDS', t:'Most own goals', f:'The 2018 World Cup in Russia set the record for most own goals in a single tournament — 12 — more than doubling any previous record.'},
{c:'RECORDS', t:'Six former champions', f:'The 2022 World Cup was the first in which all 6 former champions that qualified (Germany, Argentina, France, Brazil, Spain, England) reached at least the round of 16.'},
{c:'RECORDS', t:'100% conversion record', f:'West Germany\'s Gerd Müller scored 14 goals in 13 games across two tournaments — a goals-per-game record that has never been beaten by a high-volume scorer.'},
{c:'RECORDS', t:'Most yellow cards in a tournament', f:'The 2006 World Cup in Germany saw 28 red cards and 345 yellow cards — far more than any other tournament, partly due to stricter enforcement of the offside rule.'},
{c:'RECORDS', t:'Messi and Ronaldo WC records', f:'Messi (13 goals, 6 tournaments) and Ronaldo (8 goals, 6 tournaments) are joint holders of the record for most World Cup appearances. Only Messi is still playing.'},

// ── GOALS ─────────────────────────────────────────────────────────────────────
{c:'GOALS', t:'Pelé\'s debut goal', f:'Pelé scored Brazil\'s first goal of the 1958 tournament against Wales in the quarter-final — aged just 17. He went on to score 6 goals as Brazil won their first World Cup.'},
{c:'GOALS', t:'Bergkamp\'s wonder goal', f:'Dennis Bergkamp\'s last-minute winner for Netherlands against Argentina at France 1998 is regularly voted one of the greatest goals ever scored. A perfectly controlled chest, then volley from a 60-yard pass.'},
{c:'GOALS', t:'Maradona\'s Goal of the Century', f:'Maradona\'s second goal against England in the 1986 quarter-final — a 60-metre solo run beating five defenders — was voted the Goal of the Century by FIFA in 2002.'},
{c:'GOALS', t:'Archie Gemmill 1978', f:'Archie Gemmill\'s solo goal for Scotland vs Netherlands at the 1978 World Cup is one of the tournament\'s most celebrated. It made the score 3–1 — but Scotland needed two more and went out.'},
{c:'GOALS', t:'Zinedine Zidane', f:'Zidane scored two headers in the 1998 World Cup final — rare for a player not known for his aerial ability. France beat Brazil 3–0, their first World Cup triumph.'},
{c:'GOALS', t:'James Rodríguez 2014', f:'James Rodríguez\'s volley against Uruguay at Brazil 2014 — controlling a 40-yard pass on his chest and volleying into the corner — won the Puskás Award for goal of the year.'},
{c:'GOALS', t:'Mbappé\'s hat-trick', f:'Kylian Mbappé scored a hat-trick in the 2022 World Cup final against Argentina — the first hat-trick in a final since Geoff Hurst in 1966. France still lost on penalties.'},
{c:'GOALS', t:'Messi\'s 2022 final', f:'In the 2022 World Cup final, Messi scored twice in normal time against France. Argentina needed a 3–3 comeback from 2–0 up, then won on penalties. Widely called the greatest World Cup final ever played.'},
{c:'GOALS', t:'Own goals surge', f:'The 2018 tournament in Russia saw 12 own goals — more than any other World Cup. The previous record for a whole tournament was just 6.'},
{c:'GOALS', t:'Fontaine\'s record', f:'Just Fontaine scored 13 goals in just 6 games at the 1958 World Cup. This includes a hat-trick in the third-place play-off when he\'d already been knocked out. No player has ever got close to this record.'},
{c:'GOALS', t:'Lev Yashin — zero goals conceded', f:'Soviet goalkeeper Lev Yashin kept clean sheets in all four group matches at the 1966 World Cup — conceding zero goals before the USSR were knocked out. He\'s considered the greatest goalkeeper in history.'},
{c:'GOALS', t:'Robin van Persie\'s header', f:'Robin van Persie\'s diving header against Spain at Brazil 2014 — running onto Daley Blind\'s 40-yard ball at full pace, parallel to the ground — became one of the tournament\'s defining images.'},
{c:'GOALS', t:'Carlos Alberto 1970', f:'Carlos Alberto\'s low driving finish to complete Brazil\'s 4–1 win against Italy in the 1970 final — a team move involving 9 outfield players — is often called the greatest team goal in football history.'},
{c:'GOALS', t:'Teddy Sheringham header', f:'England\'s David Beckham and Paul Scholes connected for Teddy Sheringham\'s 90th-minute equaliser against Romania in 1998 — one of football\'s most celebrated late goals that still wasn\'t enough.'},
{c:'GOALS', t:'The Panenka', f:'Antonín Panenka\'s chipped penalty in the 1976 European Championship inspired a whole genre of penalty-taking. Zidane did it in the 2006 World Cup final. The technique is now named after Panenka.'},
{c:'GOALS', t:'Thomas Müller hat-trick', f:'Thomas Müller scored a hat-trick vs Portugal and another vs USA at the 2014 World Cup — ending up as the tournament\'s top scorer with 5 goals despite missing the semi-final.'},
{c:'GOALS', t:'Germany 7 Brazil 1', f:'Germany\'s 7–1 semi-final demolition of Brazil on home soil at the 2014 World Cup is the most shocking result in tournament history. Five of the goals came in 18 minutes.'},
{c:'GOALS', t:'Milla\'s corner flag dance', f:'Roger Milla would celebrate every goal for Cameroon in 1990 by dancing around the corner flag. At 38 years old, he scored 4 goals as Cameroon reached the quarter-finals — the first African team to do so.'},
{c:'GOALS', t:'Klose\'s overhead kick', f:'Miroslav Klose scored an overhead kick against Ecuador in the 2006 World Cup group stage — one of the most acrobatic goals of his 16-goal haul.'},
{c:'GOALS', t:'Saudi Arabia vs Argentina 2022', f:'Saudi Arabia\'s 2–1 win over Argentina — the reigning Copa América champions — in the 2022 group stage is considered one of the greatest upsets in World Cup history.'},
{c:'GOALS', t:'Senegal 2002', f:'Senegal beat France — the reigning world and European champions — 1–0 in the opening match of the 2002 World Cup. Papa Bouba Diop scored the goal; the whole team celebrated by dancing around his shirt.'},

// ── PLAYERS ───────────────────────────────────────────────────────────────────
{c:'PLAYERS', t:'Pelé at three World Cups', f:'Pelé played at three World Cups (1958, 1962, 1966) — but was injured and didn\'t feature heavily in two of them. He only truly starred in 1958 and 1970, the year Brazil\'s greatest team won their third title.'},
{c:'PLAYERS', t:'Pelé and Ronaldo', f:'Pelé and Ronaldo (Brazil) both scored 12 goals at World Cup tournaments — but neither holds the record. Miroslav Klose\'s 16 goals puts him comfortably clear at the top.'},
{c:'PLAYERS', t:'Ronaldo (Brazil) comeback', f:'Ronaldo Nazário suffered what appeared to be a career-ending knee injury before the 1998 World Cup. He came back to score 8 goals and win the 2002 tournament — one of football\'s greatest comebacks.'},
{c:'PLAYERS', t:'Zidane\'s headbutt', f:'Zinedine Zidane was sent off in extra time of the 2006 World Cup final for headbutting Marco Materazzi in the chest. France lost on penalties. Zidane never played football again.'},
{c:'PLAYERS', t:'Gazza\'s tears', f:'Paul Gascoigne\'s tears after receiving a yellow card that would have ruled him out of the 1990 World Cup final — had England got there — became one of the most iconic images in English football history.'},
{c:'PLAYERS', t:'Beckenbauer', f:'Franz Beckenbauer is one of only two people (along with Didier Deschamps) to win the World Cup as both player and manager. He led West Germany to the title in 1974 and managed them to it again in 1990.'},
{c:'PLAYERS', t:'Ronaldo\'s 6th World Cup', f:'Cristiano Ronaldo became just the second player (alongside Messi) to play at six World Cup tournaments in 2026. His 214 caps are the most in men\'s international football history.'},
{c:'PLAYERS', t:'Messi finally wins', f:'Lionel Messi\'s World Cup story ended in triumph at Qatar 2022 after agonising exits in 2006 (QF), 2010 (R16), 2014 (final), 2018 (R16), and 2022 (winner). He won the Golden Ball for best player three times.'},
{c:'PLAYERS', t:'Cafu and Roberto Carlos', f:'Brazil\'s Cafu and Roberto Carlos were perhaps the greatest full-back partnership in World Cup history. Both could play as wingers. Together they helped Brazil win the 2002 title.'},
{c:'PLAYERS', t:'Ronaldinho 2002', f:'Ronaldinho\'s free kick lobbed England goalkeeper David Seaman from 40 yards in the 2002 World Cup quarter-final. Many thought it was a cross. It was the most memorable moment of the 2002 tournament.'},
{c:'PLAYERS', t:'Lev Yashin', f:'Lev Yashin, the Soviet goalkeeper, is the only goalkeeper in history to win the Ballon d\'Or (1963). He is widely considered the greatest goalkeeper of all time.'},
{c:'PLAYERS', t:'Garrincha 1962', f:'Garrincha — "Little Bird" — is considered by many Brazilians as the greatest player in their history. At the 1962 World Cup, while Pelé was injured, Garrincha single-handedly dragged Brazil to the title.'},
{c:'PLAYERS', t:'Diego Forlán 2010', f:'Uruguay\'s Diego Forlán won the Golden Ball as best player at the 2010 World Cup — despite Uruguay only finishing fourth. His volleyed winner against Germany in the semi-final was stunning.'},
{c:'PLAYERS', t:'Paolo Maldini', f:'Paolo Maldini played at four World Cups for Italy (1990, 1994, 1998, 2002). Italy reached the final in 1990 and 1994 with Maldini as a cornerstone of their defence.'},
{c:'PLAYERS', t:'Ronaldo vs Cafú', f:'At the 2002 World Cup final, Brazil\'s Ronaldo scored both goals in a 2–0 win over Germany. He finished as top scorer with 8 goals and won the Golden Boot. He was named Player of the Tournament.'},
{c:'PLAYERS', t:'Wayne Rooney', f:'Wayne Rooney scored zero World Cup goals for England across his first two tournaments (2004 and 2006) before a foot injury ended his 2006 campaign in disappointment. England reached the quarter-finals both times.'},
{c:'PLAYERS', t:'Oliver Kahn 2002', f:'Germany goalkeeper Oliver Kahn won the 2002 World Cup Golden Ball — the only goalkeeper ever to win the award. Despite Germany losing the final 2–0 to Brazil, Kahn was magnificent throughout.'},
{c:'PLAYERS', t:'Son Heung-min', f:'South Korea\'s Son Heung-min was forced to play the 2022 World Cup wearing a protective face mask after breaking his eye socket just weeks before the tournament. South Korea still reached the Round of 16.'},
{c:'PLAYERS', t:'Lamine Yamal 2024', f:'Lamine Yamal of Spain scored his first senior international goal in the Euro 2024 semi-final — on the eve of his 17th birthday. He arrives at the 2026 World Cup as possibly the most exciting teenager in football history.'},
{c:'PLAYERS', t:'Andrés Iniesta 2010', f:'Andrés Iniesta scored the winning goal in the 2010 World Cup final against Netherlands — his first goal of the tournament, in the 116th minute. He was named Player of the Match.'},
{c:'PLAYERS', t:'Xavi and Iniesta', f:'Spain\'s 2010 triumph was built on possession football. In the final, Spain completed 559 passes to the Netherlands\' 328. Xavi and Iniesta orchestrated one of the most dominant performances of any World Cup winning team.'},

// ── HOSTS ─────────────────────────────────────────────────────────────────────
{c:'HOSTS', t:'Mexico 1970', f:'Mexico City\'s altitude (2,240 metres above sea level) at the 1970 World Cup made breathing difficult for players from sea-level nations. Brazil, with their samba style, adapted brilliantly.'},
{c:'HOSTS', t:'Argentina 1978', f:'Argentina hosted and won the 1978 World Cup under a military dictatorship. There were widespread allegations of match-fixing, particularly in the controversial result against Peru in the final group stage.'},
{c:'HOSTS', t:'Mexico 86 earthquake', f:'Mexico hosted the 1986 World Cup just eight months after a devastating earthquake killed 10,000 people. The tournament became a powerful symbol of the country\'s resilience.'},
{c:'HOSTS', t:'Italia 90', f:'The 1990 World Cup in Italy was the most defensive tournament in history. The average goals per game was just 2.21 — prompting FIFA to change the offside law and introduce the back-pass rule.'},
{c:'HOSTS', t:'USA 94 — breaking records', f:'Despite predictions of failure, USA 1994 broke every attendance record. Average crowds exceeded 68,000 — a figure no subsequent tournament has matched. The Americans were bitten by football fever.'},
{c:'HOSTS', t:'France 98 — opening night', f:'The 1998 World Cup opened with reigning champions Brazil vs Scotland in Paris. A Cafu cross led to a defensive calamity and Brazil won 2–1. France went on to win the tournament.'},
{c:'HOSTS', t:'Johannesburg 2010', f:'The 2010 World Cup final in Johannesburg was the first played in Africa. The vuvuzela — the plastic horn blown continuously by South African fans — was heard on broadcasts worldwide and divided opinion.'},
{c:'HOSTS', t:'Brazil 2014', f:'Brazil spent an estimated $15 billion hosting the 2014 World Cup. Stadium construction triggered protests across the country — Brazilians argued the money should have been spent on hospitals and schools.'},
{c:'HOSTS', t:'Qatar climate', f:'Qatar 2022 moved to November-December for the first time in history to avoid temperatures of 45°C. Some stadia used air conditioning — a surreal sight at a football tournament.'},
{c:'HOSTS', t:'USA 2026 — 11 cities', f:'The 2026 World Cup will be played across 16 venues in 11 US cities, plus 3 in Mexico and 2 in Canada. The final will be played at MetLife Stadium in New York/New Jersey.'},
{c:'HOSTS', t:'Canada\'s return', f:'Canada last hosted a men\'s World Cup match in 1986 — as a co-host with Mexico. In 2026, they return as co-host on home soil with arguably their best team in history.'},
{c:'HOSTS', t:'Mexico\'s third World Cup', f:'Mexico in 2026 becomes the first nation to host World Cup matches three times (1970, 1986, 2026). The Estadio Azteca in Mexico City will host matches for the third time — a world record.'},
{c:'HOSTS', t:'Wembley 1966', f:'The 1966 World Cup final was watched by a UK TV audience of 32 million — roughly 55% of the UK population at the time. It remains the most watched event in UK television history.'},
{c:'HOSTS', t:'Maracanã magic', f:'Rio\'s Maracanã Stadium opened for the 1950 World Cup with a reported capacity of nearly 200,000. Today it holds 78,000. The original capacity included standing sections on terraces surrounding the pitch.'},
{c:'HOSTS', t:'South Korea 2002 controversy', f:'South Korea\'s 2002 run to the semi-finals generated enormous controversy. Italy and Spain both had goals disallowed in games against the hosts, leading to accusations of referee bias.'},
{c:'HOSTS', t:'Germany 2006 — summer fairy tale', f:'The 2006 World Cup in Germany transformed the country\'s image. Dubbed the "Summer Fairy Tale", it saw a wave of German patriotism and good-natured football celebrations not seen since reunification.'},
{c:'HOSTS', t:'Russia 2018 — surprise host', f:'Russia 2018 was controversial before a ball was kicked due to the host nation\'s political tensions with the West. On the pitch, France won it and Croatia produced a miraculous run to the final.'},

// ── UPSETS ────────────────────────────────────────────────────────────────────
{c:'UPSETS', t:'USA beat England 1950', f:'In what\'s considered the greatest upset in World Cup history, the USA beat England 1–0 in 1950. England were strong favourites; a part-time dishwasher named Joe Gaetjens scored the winner.'},
{c:'UPSETS', t:'North Korea 1966', f:'North Korea beat Italy 1–0 at the 1966 World Cup — one of the biggest shocks in the tournament\'s history. They went on to lead Portugal 3–0 in the quarter-final before Eusébio scored four goals and Portugal won 5–3.'},
{c:'UPSETS', t:'Senegal 2002', f:'Senegal beat France — the reigning world and European champions — 1–0 in the opening match of the 2002 World Cup. It remains one of the biggest shocks in opening day history.'},
{c:'UPSETS', t:'South Korea 2002', f:'South Korea beat Spain in the quarter-finals of the 2002 World Cup on penalties — despite having two goals disallowed in controversial circumstances. They then beat Germany\'s semi-final opponents to reach the last four.'},
{c:'UPSETS', t:'Greece Euro 2004', f:'While not a World Cup, Greece\'s Euro 2004 triumph inspired underdogs everywhere. Three of their players subsequently featured at the 2006 World Cup where they were eliminated in the group stage.'},
{c:'UPSETS', t:'Germany 7-1 Brazil 2014', f:'Brazil\'s 7–1 semi-final thrashing at home in 2014 remains the biggest shock in modern World Cup history. Brazil had not lost a home competitive match since 1975.'},
{c:'UPSETS', t:'Algeria 2014', f:'Algeria scored 4 goals against Germany in the 2014 round of 16 — but still lost 2–1 in extra time. It was the most goals Germany had conceded while winning a World Cup knockout game.'},
{c:'UPSETS', t:'Saudi Arabia 2022', f:'Saudi Arabia beat Argentina 2–1 in the 2022 group stage. Argentina were on a 36-game unbeaten run and had won the Copa América. Saudi Arabia\'s high defensive line and clinical counterattacking stunned the world.'},
{c:'UPSETS', t:'Cameroon 1990', f:'Cameroon beat reigning champions Argentina in the opening match of the 1990 World Cup — despite finishing with nine men. Roger Milla came off the bench and changed the game.'},
{c:'UPSETS', t:'Japan beats Germany 2022', f:'Japan came from behind to beat Germany 2–1 and Spain 2–1 at Qatar 2022 — stunning results against two former World Cup winners. Japan topped their group despite those two being among the pre-tournament favourites.'},
{c:'UPSETS', t:'Morocco 2022', f:'Morocco beat Portugal in the quarter-finals of the 2022 World Cup — making history as the first African and Arab nation to reach the last four. They had also knocked out Belgium and Spain along the way.'},
{c:'UPSETS', t:'Spain 2010 — almost out', f:'Spain lost their opening 2010 World Cup group game 1–0 to Switzerland. They then won every remaining match and the tournament — the only team to win a World Cup after losing their opening game.'},
{c:'UPSETS', t:'The Miracle of Bern', f:'Hungary were unbeaten in four years before the 1954 World Cup final and had beaten West Germany 8–3 in the group stage. West Germany won the final 3–2 in one of football\'s most shocking results.'},
{c:'UPSETS', t:'Republic of Ireland 1990', f:'The Republic of Ireland reached the World Cup quarter-finals for the first time in 1990. Managed by Jack Charlton, they beat Romania on penalties before losing to the hosts Italy.'},
{c:'UPSETS', t:'Denmark 1992 effect', f:'Denmark won Euro 1992 as late replacements for Yugoslavia — inspiring a generation. At the 1998 World Cup, they beat Nigeria and reached the quarter-finals, losing to Brazil.'},
{c:'UPSETS', t:'Italy out in group stage 2010', f:'Italy arrived at the 2010 World Cup as defending champions. They were eliminated in the group stage after finishing bottom of a group containing Paraguay, New Zealand and Slovakia.'},
{c:'UPSETS', t:'England vs Iceland Euro 2016', f:'Iceland beat England 2–1 at Euro 2016 in one of the greatest international shocks ever. A nation of 330,000 people eliminated England and their thunderclap celebration became iconic.'},

// ── ODDITIES ──────────────────────────────────────────────────────────────────
{c:'ODDITIES', t:'Pickles the dog', f:'The Jules Rimet Trophy was stolen before the 1966 World Cup in England. It was found a week later by a dog named Pickles under a hedge in south London. Pickles became a national hero.'},
{c:'ODDITIES', t:'Ball disputes in 1930', f:'In the 1930 World Cup final, Argentina and Uruguay could not agree on which ball to use. They played the first half with Argentina\'s ball (Argentina led 2–1) then the second with Uruguay\'s (Uruguay won 4–2).'},
{c:'ODDITIES', t:'Bert Patenaude', f:'Bert Patenaude of the USA scored the first hat-trick in World Cup history in 1930. It wasn\'t officially recognised until 2006 — 76 years later — when FIFA reviewed the records.'},
{c:'ODDITIES', t:'No neutrals for Zaire', f:'Zaire\'s defender Mwepu Ilunga famously ran out of the wall and kicked a free kick upfield during a 1974 group stage game against Brazil. Many assumed he was confused. Others suggest he was deliberately wasting time.'},
{c:'ODDITIES', t:'El Salvador\'s goalkeeper', f:'El Salvador conceded 10 goals to Hungary in the 1982 World Cup. Their goalkeeper, Magico González, was considered one of the most talented players of his generation — but the team around him was not.'},
{c:'ODDITIES', t:'Colombia\'s own goal', f:'Andrés Escobar scored an own goal for Colombia against the USA at the 1994 World Cup. Ten days after returning home, he was shot dead outside a restaurant in Medellín. His murder shocked the world of football.'},
{c:'ODDITIES', t:'The Disgrace of Gijón', f:'At the 1982 World Cup, West Germany beat Austria 1–0 in a result that eliminated Algeria. Both teams appeared to play out the result they needed. FIFA subsequently changed the rules so final group games are played simultaneously.'},
{c:'ODDITIES', t:'North Korea\'s players disappeared', f:'North Korea\'s players who lost 3–0 to Portugal at the 1966 World Cup quarter-final — having led 3–0 at half time — reportedly never appeared in public life again. The true story of what happened to them remains unknown.'},
{c:'ODDITIES', t:'Penalty by a team that lost', f:'At the 2018 World Cup, Adnan Januzaj scored a stunning winner for Belgium to beat England. But England\'s manager Gareth Southgate later admitted he had deliberately rested players to finish second in the group and avoid a harder draw.'},
{c:'ODDITIES', t:'Zidane\'s last act', f:'Zinedine Zidane\'s final act in professional football was being sent off for headbutting Marco Materazzi in the chest in the 2006 World Cup final. He had previously scored an audacious Panenka penalty. France lost on penalties.'},
{c:'ODDITIES', t:'Colombia 1994', f:'Colombia were considered dark-horses for the 1994 World Cup after receiving praise from Pelé. They lost their opening game 3–1 to Romania and were eliminated in the group stage — one of the biggest disappointments in tournament history.'},
{c:'ODDITIES', t:'Lampard\'s ghost goal', f:'Frank Lampard\'s shot clearly crossed the German goal-line at the 2010 World Cup round of 16 but was not given. England lost 4–1. The incident directly led to FIFA trialling goal-line technology.'},
{c:'ODDITIES', t:'Maradona drug ban', f:'Diego Maradona was sent home from the 1994 World Cup after testing positive for ephedrine — a banned stimulant. Argentina were knocked out in the round of 16 without him.'},
{c:'ODDITIES', t:'England 1950 — no Wolves', f:'England\'s 1950 World Cup squad didn\'t include several players from Wolverhampton Wanderers — who were rivals of the club whose chairman sat on the Football Association selection committee.'},
{c:'ODDITIES', t:'1938 — colonial players', f:'In 1938, multiple African and Asian countries were entered into the World Cup but forced to qualify via European rounds because FIFA refused to create separate qualification pathways. Many withdrew in protest.'},
{c:'ODDITIES', t:'Higuaín 2014 final', f:'Gonzalo Higuaín missed a one-on-one in the 2014 World Cup final when the score was 0–0. Argentina lost 1–0 in extra time. Higuaín was inconsolable — the moment defined his career narrative.'},
{c:'ODDITIES', t:'The Battle of Santiago', f:'The 1962 match between Chile and Italy was so violent it became known as "The Battle of Santiago". Two Italians were sent off, players were punched, and the English referee needed police protection.'},
{c:'ODDITIES', t:'Robben\'s revenge', f:'Arjen Robben missed a penalty in the 2010 World Cup final shootout — which the Netherlands lost 1–0 to Spain. Four years later at Brazil 2014, his late penalty won the opening group game against Spain. He described it as closure.'},
{c:'ODDITIES', t:'Ball-boys', f:'The 2010 World Cup in South Africa used ball-boys for the first time in tournament history — helping the pace of play. It is now standard practice at all major tournaments.'},
{c:'ODDITIES', t:'1950 — no knockout rounds', f:'The 1950 World Cup had no semi-finals or final in the traditional sense. A final round-robin group of four teams decided the winner. Brazil needed just a draw in the last game vs Uruguay — and lost.'},

// ── WC2026 ────────────────────────────────────────────────────────────────────
{c:'NOW', t:'48 teams', f:'The 2026 World Cup is the first with 48 teams — up from 32. The extra 16 places were largely allocated to Africa (9 teams), Asia (8), North/Central America (6) and South America (6+1 play-off).'},
{c:'NOW', t:'Three hosts', f:'For the first time, the World Cup is hosted by three nations: the USA, Canada and Mexico. Most games are in the USA (11 cities), with 3 in Mexico and 2 in Canada.'},
{c:'NOW', t:'The Azteca hat-trick', f:'The Estadio Azteca in Mexico City will host World Cup matches for the third time in 2026 — having previously hosted matches in 1970 and 1986. No stadium has done this before.'},
{c:'NOW', t:'MetLife final', f:'The 2026 World Cup final will be played at MetLife Stadium in East Rutherford, New Jersey — the home of the NFL\'s New York Giants and Jets. Capacity: 82,500.'},
{c:'NOW', t:'12 groups', f:'The 2026 group stage features 12 groups of 4 teams. The top 2 from each group advance, plus the 8 best third-placed teams — making the Round of 32 the first knockout round.'},
{c:'NOW', t:'104 matches', f:'The 2026 World Cup will feature 104 matches — compared to 64 in previous 32-team tournaments. The tournament runs from June 11 to July 19, covering 39 days.'},
{c:'NOW', t:'Opening match', f:'The 2026 World Cup opens on June 11 with Mexico vs South Africa at Estadio Azteca in Mexico City — a historic occasion as Mexico play their first home World Cup match since 1986.'},
{c:'NOW', t:'USA returns', f:'The USA last hosted the World Cup in 1994 — when they set all-time attendance records. Thirty-two years later they return as hosts with arguably the strongest US squad in history.'},
{c:'NOW', t:'Canada\'s golden generation', f:'Canada qualified for only their second World Cup ever in 2022 — and now return as co-hosts with Alphonso Davies, Jonathan David and a genuinely exciting squad.'},
{c:'NOW', t:'Messi\'s farewell?', f:'Lionel Messi (38) returns for what is almost certainly his final World Cup — on the same continent where he grew up in Argentina. He needs just 3 goals to break Klose\'s all-time record of 16.'},
{c:'NOW', t:'Ronaldo at 41', f:'Cristiano Ronaldo is 41 at the 2026 World Cup — the oldest outfield player to ever play in the tournament. He and Messi both appear at a record-equalling sixth World Cup.'},
{c:'NOW', t:'Lamine Yamal', f:'Lamine Yamal arrives at the 2026 World Cup aged just 18 — having won the European Championship with Spain in 2024. He is widely considered the most exciting young player in the world.'},
{c:'NOW', t:'England\'s wait', f:'England\'s 60-year wait for a World Cup since their 1966 triumph is the longest active wait of any former World Cup winner. Each tournament they are among the pre-tournament favourites.'},
{c:'NOW', t:'Brazil\'s 24-year drought', f:'Brazil have not won the World Cup since 2002. No other nation with multiple titles has gone as long between wins. Vinicius Jr and a strong squad make them strong contenders in 2026.'},
{c:'NOW', t:'France defend', f:'France are defending champions having beaten Argentina in an extraordinary 2022 final that ended 3–3 before going to penalties. Mbappé scored a hat-trick in the final but still ended on the losing side.'},
{c:'NOW', t:'Scotland returns', f:'Scotland are at their first World Cup since France 1998 — a 28-year gap. They qualified behind a group containing the reigning European champions Spain.'},
{c:'NOW', t:'New faces', f:'The 2026 World Cup features 12 debutant nations — including debut appearances from teams like Cape Verde, Curaçao, Jordan and Uzbekistan.'},
{c:'NOW', t:'AI and VAR', f:'The 2026 World Cup will use the most advanced version of semi-automated offside technology ever deployed — using 12 cameras per stadium and AI tracking to make offside decisions in seconds rather than minutes.'},
{c:'NOW', t:'Harry Kane\'s record hunt', f:'Harry Kane goes into the 2026 World Cup with 8 World Cup goals. He needs 8 more to equal Klose\'s record — a tall order, but with 3 group games and potentially 7 in total, not impossible.'},
{c:'NOW', t:'Jude Bellingham', f:'Jude Bellingham will be 23 at the 2026 World Cup — after already playing at two tournaments. He is widely regarded as England\'s best chance of a match-winner in the mould of Zidane or Messi.'},
{c:'NOW', t:'No Russia', f:'Russia have been banned from the 2026 World Cup due to their invasion of Ukraine — meaning their squad of players, many of whom play in top European leagues, will not participate.'},
{c:'NOW', t:'Italy — again', f:'Italy failed to qualify for the 2022 World Cup and 2026 World Cup — extraordinary for a four-time champion. They\'ve now missed two consecutive tournaments after also missing the 2018 edition.'},
{c:'NOW', t:'Ticket demand', f:'The 2026 World Cup received over 40 million ticket applications for 3 million available tickets — the highest demand in tournament history, driven largely by the expanded 48-team format.'},
{c:'NOW', t:'English Premier League', f:'More players in the 2026 World Cup squads play in the English Premier League than in any other league — roughly 180 players from 32 squads represent PL clubs.'},

// ── EXTRA FACTS ───────────────────────────────────────────────────────────────
{c:'HISTORY', t:'First substitution', f:'Substitutes were not allowed at the World Cup until 1970. Since then, three substitutes per team have been the norm, extended to five during the COVID era and kept for 2026.'},
{c:'HISTORY', t:'VAR arrives', f:'Video Assistant Referee (VAR) was first used at the 2018 World Cup in Russia. France benefited from an early VAR penalty decision in the final — a moment that shaped the outcome.'},
{c:'RECORDS', t:'Gerd Müller\'s ratio', f:'Gerd Müller scored 14 World Cup goals in just 13 appearances across 1970 and 1974 — a ratio that has never been matched by a player with more than 5 goals in the tournament.'},
{c:'PLAYERS', t:'Eusébio 1966', f:'Eusébio of Portugal scored 9 goals at the 1966 World Cup — including four in a single match against North Korea. He wept after Portugal\'s semi-final defeat to England. His goals brought him the Golden Boot.'},
{c:'PLAYERS', t:'Bobby Charlton', f:'Bobby Charlton played for England in 1966, 1962 and 1970 — scoring 3 World Cup goals. He and his brother Jack Charlton won the 1966 World Cup together in the same England side.'},
{c:'GOALS', t:'Brazilball 1970', f:'Brazil\'s 1970 team is widely considered the finest in World Cup history. They won every game, scored 19 goals in 6 matches, and produced football of such beauty that their style was dubbed "the beautiful game".'},
{c:'UPSETS', t:'France 2002', f:'France arrived at the 2002 World Cup as world and European champions. They were eliminated in the group stage without scoring a single goal — one of the greatest defending-champion collapses in history.'},
{c:'ODDITIES', t:'Refereeing blunders', f:'The 1966 World Cup final referee Gottfried Dienst awarded England\'s controversial third goal after the ball appeared to bounce off the crossbar, over — and some say not over — the line. He consulted a Soviet linesman who confirmed it. Germany still dispute it.'},
{c:'RECORDS', t:'Most World Cup final goals', f:'Kylian Mbappé has scored 4 World Cup final goals — more than any other player. He scored in 2018 (a 4–2 win) and scored a hat-trick in 2022 but still lost.'},
{c:'PLAYERS', t:'Dembélé\'s assists 2018', f:'Ousmane Dembélé provided the assist for Paul Pogba\'s goal and played a pivotal role in France\'s 2018 World Cup triumph — scoring his only goal of the tournament against Argentina in the round of 16.'},
{c:'HISTORY', t:'Total Football', f:'The Netherlands\' 1974 squad pioneered "Total Football" — where outfield players could interchange positions fluidly. Johan Cruyff led them to the final, where they lost to West Germany 2–1.'},
{c:'PLAYERS', t:'Johan Cruyff', f:'Johan Cruyff never won the World Cup — the Netherlands lost the 1974 final to West Germany. He controversially refused to play at the 1978 World Cup, a decision linked to a kidnapping attempt on his family.'},
{c:'RECORDS', t:'Most consecutive WC appearances', f:'Brazil and Germany are the only two nations to have qualified for every single World Cup since the tournament began in 1930. Brazil holds the record with 22 consecutive appearances.'},
{c:'NOW', t:'Morocco\'s ambition', f:'Morocco, having reached the semi-finals in 2022, arrive at 2026 with the ambition of going one step further. Manager Walid Regragui has assembled a squad that blends European experience with African passion.'},
{c:'NOW', t:'Argentina defending', f:'Argentina arrive in 2026 as defending champions — a team captained by Messi at 38, the oldest World Cup defending champion captain in history. They are drawn in Group J.'},
{c:'HOSTS', t:'Azteca atmosphere', f:'The Estadio Azteca is widely considered the most atmospheric football ground in the world. England vs Germany, Brazil vs Germany, and many of the greatest World Cup moments have taken place there.'},
{c:'GOALS', t:'Cafu cross 1998', f:'In the 1998 World Cup final, Zinedine Zidane scored two headers — both from Cafu crosses. It remains the only World Cup final where the same player scored two headers.'},
{c:'PLAYERS', t:'Buffon\'s 2006', f:'Gianluigi Buffon conceded just 2 goals in Italy\'s run to the 2006 World Cup title — and both were own goals. He kept clean sheets against Germany in the semi-final and France in the final.'},
{c:'ODDITIES', t:'Penalty without a player', f:'In the 1994 World Cup final, Italy\'s Roberto Baggio missed the decisive penalty — sending the ball over the crossbar. Baggio later said it was "a moment that has never left me".'},
{c:'RECORDS', t:'Youngest squad 2026', f:'France\'s average squad age for the 2026 World Cup is one of the lowest ever seen for a title favourite — with players like Camavinga (22), Tchouaméni (25) and Saliba (24) complementing the older generation.'},
];

// Shuffle array using Fisher-Yates
function shuffleFacts(arr) {
  var a = arr.slice();
  for (var i = a.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = a[i]; a[i] = a[j]; a[j] = tmp;
  }
  return a;
}

